-- LLM-drafted translations (needs_review = TRUE throughout) of Level 4's
-- lesson content (seeded by migration 0035), into the 7 non-English
-- locales — same posture as migrations 0021, 0038, 0039.
INSERT INTO lesson_translations (lesson_id, locale, title, content) VALUES
    ('00000000-0000-0000-0000-000000003101', 'pcm', 'Make You Understand Attachment Style', 'Attachment theory dey explain pattern for how people dey relate to closeness and separation for relationship, wey mostly come from how dem take care of you when you small. For general, dem dey describe dis patterns as: secure (you comfortable with closeness and independence), anxious (you dey crave closeness, you dey fear say dem go abandon you), avoidant (you dey value independence, closeness no dey comfortable for you), and disorganized (na mixture, e dey mostly come from inconsistent or fearful care when you small).\n\nAttachment style no be life sentence or label wey you go use diagnose yourself or another person -- na lens to notice pattern wey dey repeat, like why certain relationship dynamic dey feel familiar even when e no dey work well.\n\nTo understand your own tendency fit make am easy to recognize reaction as "na my attachment pattern dey show" instead of "dis relationship don spoil finish" -- dis difference dey open room for communication and change.'),
    ('00000000-0000-0000-0000-000000003101', 'yo', 'Òye Nípa Àwọn Ìlànà Ìfarapọ̀', 'Ẹ̀kọ́ ìfarapọ̀ ń ṣàpèjúwe àwọn ìlànà nínú bí ènìyàn ṣe ní àjọṣe pẹ̀lú ìtòsí àti ìyapa nínú àjọṣe, tí ó jẹ́ àbájáde ìrírí ìtọ́jú ní ìbẹ̀rẹ̀ ayé ẹni. Ní gbogbogbòò, àwọn ìlànà wọ̀nyí ni a ṣàpèjúwe gẹ́gẹ́ bí: dídúró ṣinṣin (ìtura pẹ̀lú ìtòsí àti òmìnira), àníyàn (ìfẹ́ ìtòsí, ìbẹ̀rù ìkọ̀sílẹ̀), yíyẹra (ṣíṣe pàtàkì òmìnira, àìní ìtura pẹ̀lú ìtòsí), àti rúdurùdu (àdàpọ̀, tí ó sábà máa ń jẹ́ àbájáde ìtọ́jú tí kò dúró ṣinṣin tàbí tí ó ń dẹ́rùba).\n\nÌlànà ìfarapọ̀ kì í ṣe ìdájọ́ ayé tàbí àmì tí a fi ṣe àyẹ̀wò ara rẹ tàbí ẹlòmíràn -- ó jẹ́ ojú-ìwò láti ṣàkíyèsí àwọn ìlànà tí ń tún ṣẹlẹ̀, bí ìdí tí àwọn ìṣe àjọṣe kan fi dà bí ẹni mímọ̀ kódà nígbà tí wọn kò ṣiṣẹ́ dáadáa.\n\nÒye nípa àwọn ìwà rẹ lè mú kí ó rọrùn láti mọ ìdáhùn gẹ́gẹ́ bí "èyí ni ìlànà ìfarapọ̀ mi ń hàn jáde" dípò "àjọṣe yìí ti bàjẹ́ pátápátá" -- ìyàtọ̀ yìí ń ṣí àyè sílẹ̀ fún ìjíròrò àti ìyípadà.'),
    ('00000000-0000-0000-0000-000000003101', 'ha', 'Fahimtar Salon Kulla Alaka', 'Ka''idar kulla alaka tana bayyana tsarin yadda mutane ke mu''amala da kusanci da rabuwa a cikin dangantaka, wanda galibi ya samo asali daga yadda aka kula da su tun suna kanana. Gaba daya, ana bayyana wadannan tsare-tsare a matsayin: tsayayye (jin dadi da kusanci da yancin kai), damuwa (son kusanci, tsoron a bar su), gujewa (daraja yancin kai, rashin jin dadi da kusanci), da rashin tsari (hadewar duka, galibi sakamakon kulawa mara daidaito ko mai ban tsoro).\n\nSalon kulla alaka ba hukunci na dindindin ba ne ko lakabin da za a yi amfani da shi wajen gane kai ko wani -- madubi ne na lura da tsare-tsare masu maimaitawa, kamar dalilin da ya sa wasu alakoki ke jin sanayi ko da ba sa aiki da kyau.\n\nFahimtar dabi''unka na iya sauwaka gane martani a matsayin "wannan salon kulla alakata ne ke bayyana" maimakon "wannan dangantakar ta lalace gaba daya" -- wannan bambanci yana bude kofa ga sadarwa da canji.'),
    ('00000000-0000-0000-0000-000000003101', 'ig', 'Ịghọta Ụdị Ijikọ Mmekọrịta', 'Nkà mmụta ijikọ na-akọwa ụkpụrụ otú ndị mmadụ si enwe mmekọrịta na ịnweta ma ọ bụ ikewapụ n''mmekọrịta, nke ihe ndị mere na nlekọta mbụ na-ekpebi. N''ozuzu, a na-akọwa ụkpụrụ ndị a dị ka: nke a tụkwasịrị obi (dị mma na ịnweta na nnwere onwe), nchegbu (chọrọ ịnweta, na-atụ egwu ịhapụ), izere (na-eji nnwere onwe kpọrọ ihe, enweghị mmasị na ịnweta), na enweghị usoro (agwakọta, nke ihe ndị mere na nlekọta na-adịghị aka ike ma ọ bụ na-atụ egwu na-ekpebikarị).\n\nỤdị ijikọ abụghị ikpe ndụ ma ọ bụ akara e ji achọpụta onwe gị ma ọ bụ ndị ọzọ -- ọ bụ ụzọ iji mara ụkpụrụ ndị na-eme ugboro ugboro, dị ka ihe mere omume mmekọrịta ụfọdụ ji na-adị ka ihe amara ọbụlagodi mgbe ha adịghị arụ ọrụ nke ọma.\n\nỊghọta omume gị nwere ike ime ka ọ dị mfe ịmata azịza dị ka "nke a bụ ụdị ijikọ m na-egosipụta" karịa "mmekọrịta a emebiwo kpamkpam" -- ọdịiche a na-emepe ohere maka nkwukọrịta na mgbanwe.'),
    ('00000000-0000-0000-0000-000000003101', 'fr', 'Comprendre les Styles d''Attachement', 'La théorie de l''attachement décrit les schémas selon lesquels les personnes vivent la proximité et la séparation dans leurs relations, largement façonnés par les premières expériences de soins reçus. En général, ces schémas sont décrits comme : sécurisé (à l''aise avec la proximité et l''indépendance), anxieux (recherchant la proximité, craignant l''abandon), évitant (valorisant l''indépendance, mal à l''aise avec la proximité), et désorganisé (un mélange, souvent façonné par des soins incohérents ou effrayants).\n\nLe style d''attachement n''est ni une condamnation à vie ni une étiquette pour diagnostiquer soi-même ou autrui -- c''est un prisme permettant de remarquer des schémas récurrents, comme pourquoi certaines dynamiques relationnelles semblent familières même lorsqu''elles ne fonctionnent pas.\n\nComprendre ses propres tendances peut faciliter la reconnaissance d''une réaction comme « c''est mon schéma d''attachement qui se manifeste » plutôt que « cette relation est définitivement vouée à l''échec » -- une distinction qui ouvre la voie à la communication et au changement.'),
    ('00000000-0000-0000-0000-000000003101', 'sw', 'Kuelewa Mitindo ya Kujishikamanisha', 'Nadharia ya kujishikamanisha inaelezea mifumo ya jinsi watu wanavyohusiana na ukaribu na mgawanyiko katika mahusiano, inayoundwa zaidi na uzoefu wa awali wa malezi. Kwa jumla, mifumo hii inaelezwa kama: salama (starehe na ukaribu na uhuru), wasiwasi (kutamani ukaribu, kuogopa kuachwa), kuepuka (kuthamini uhuru, kutostarehe na ukaribu), na isiyopangika (mchanganyiko, mara nyingi ikiundwa na malezi yasiyo thabiti au ya kutisha).\n\nMtindo wa kujishikamanisha si hukumu ya maisha wala lebo ya kujichunguza wewe mwenyewe au wengine -- ni kioo cha kutambua mifumo inayojirudia, kama kwa nini baadhi ya mienendo ya uhusiano huhisi ya kawaida hata isipofanya kazi vizuri.\n\nKuelewa tabia zako mwenyewe kunaweza kurahisisha kutambua mwitikio kama "huu ni mtindo wangu wa kujishikamanisha unajitokeza" badala ya "uhusiano huu umeharibika kabisa" -- tofauti hii hufungua nafasi ya mawasiliano na mabadiliko.'),
    ('00000000-0000-0000-0000-000000003101', 'ar', 'فهم أنماط التعلق', 'تصف نظرية التعلق الأنماط التي يتعامل بها الناس مع القرب والانفصال في العلاقات، والتي تتشكل إلى حد كبير من خلال تجارب الرعاية المبكرة. بشكل عام، تُوصف هذه الأنماط بأنها: آمن (مرتاح مع القرب والاستقلالية)، قلق (يتوق إلى القرب، يخشى الهجر)، متجنب (يقدّر الاستقلالية، غير مرتاح مع القرب)، وفوضوي (مزيج، غالبًا ما تشكله رعاية غير متسقة أو مخيفة).\n\nنمط التعلق ليس حكمًا مدى الحياة أو وسمًا لتشخيص نفسك أو الآخرين -- إنه عدسة لملاحظة الأنماط المتكررة، مثل سبب شعور ديناميكيات علاقة معينة بالألفة حتى عندما لا تعمل بشكل جيد.\n\nفهم ميولك الخاصة يمكن أن يسهّل التعرف على استجابة ما بأنها "هذا نمط تعلقي يظهر" بدلًا من "هذه العلاقة محكوم عليها بالفشل بالتأكيد" -- وهذا التمييز يفتح مجالًا للتواصل والتغيير.'),

    ('00000000-0000-0000-0000-000000003102', 'pcm', 'Setting and Holding Boundaries', 'Boundary na clear statement of wetin you need make you feel safe and respected for relationship -- e no be punishment, and e no be say make you control another person behavior. Boundary dey describe wetin YOU go do, e no be demand for wetin the other person must do: "I go leave the conversation if e become disrespectful" instead of "you must stop to dey disrespectful."\n\nFor people wey get history of trauma, to set boundary fit feel unsafe at first, especially if dem don punish directness for their past relationship before. E common to over-apologize or soften boundary until e lose meaning. To practice boundary for small matter first fit help build the skill before you go need am for something wey matter well-well.\n\nBoundary wey you talk but you no hold am no be real boundary -- consistency, even for small way, na im dey make am trustworthy for both you and the other person.'),
    ('00000000-0000-0000-0000-000000003102', 'yo', 'Ṣíṣètò àti Dídúró sórí Àwọn Òpin', 'Òpin jẹ́ àlàyé tí ó ṣe kedere nípa ohun tí o nílò kí o lè nímọ̀lára àbò àti ọ̀wọ̀ nínú àjọṣe -- kì í ṣe ìyà, kì í sì í ṣe nípa ṣíṣàkóso ìwà ẹlòmíràn. Òpin ń ṣàpèjúwe ohun tí ÌWỌ yóò ṣe, kì í ṣe ìbéèrè fún ohun tí ẹlòmíràn gbọ́dọ̀ ṣe: "Mo máa fi ọ̀rọ̀ náà sílẹ̀ bí ó bá di àìlọ́wọ̀" dípò "o gbọ́dọ̀ dáwọ́ àìlọ́wọ̀ dúró."\n\nFún àwọn ènìyàn tí wọ́n ní ìtàn ìpalára-ọkàn, ṣíṣètò òpin lè jẹ́ àìnímọ̀lára àbò ní àkọ́kọ́, pàápàá tí àjọṣe wọn àtijọ́ bá ti fi ìyà jẹ ìtọ́ka-ọ̀rọ̀. Ó wọ́pọ̀ láti máa tọrọ àforíjì jù tàbí láti rọ̀ òpin títí ó fi pàdánù ìtumọ̀ rẹ̀. Síṣe àṣàrò òpin nínú ipò kéékèèké lè ràn láti kọ́ ọgbọ́n náà kí a tó nílò rẹ̀ níbi tí ó ṣe pàtàkì jù.\n\nÒpin tí a sọ ṣùgbọ́n tí a kò dúró sórí rẹ̀ kì í ṣe òpin gidi -- ìdúró-ṣinṣin, kódà ní ọ̀nà kéékèèké, ni ó ń mú kí ó ṣeé gbẹ́kẹ̀lé fún ìwọ àti ẹlòmíràn.'),
    ('00000000-0000-0000-0000-000000003102', 'ha', 'Kayyade da Rike Iyaka', 'Iyaka furuci ne mai tsabta na abin da kake bukata domin ka ji lafiya da girmamawa a cikin dangantaka -- ba hukunci ba ne, kuma ba game da sarrafa halayen wani ba ne. Iyaka tana bayyana abin da KAI za ka yi, ba bukata ga abin da dole wani ya yi ba: "Zan bar tattaunawar idan ta zama rashin mutunci" maimakon "dole ka daina rashin mutunci."\n\nGa mutanen da suke da tarihin rauni, kayyade iyakoki na iya jin rashin lafiya da farko, musamman idan dangantakar da suka gabata ta hukunta kai tsaye. Yana da yawa a gafarta fiye da kima ko a sassauta iyaka har sai ta rasa ma''ana. Yin atisaye da iyakoki a yanayi masu karancin hadari da farko zai iya taimakawa ginawa fasahar kafin ka bukace ta a inda ya fi muhimmanci.\n\nIyakar da aka sanar amma ba a rike ta ba ba ainihin iyaka ba ce -- dagewa, ko da ta hanyoyi kanana, ita ce take sanya ta amintacciya ga kai da wancan mutumin.'),
    ('00000000-0000-0000-0000-000000003102', 'ig', 'Ịtọ Na Idowe Oke', 'Oke bụ nkwupụta doro anya banyere ihe ị chọrọ ka ị nwee mmetụta nchekwa na nkwanye ugwu na mmekọrịta -- ọ bụghị ntaramahụhụ, ọ bụghịkwa banyere ijikwa omume onye ọzọ. Oke na-akọwa ihe GỊ ga-eme, ọ bụghị arịrịọ maka ihe onye ọzọ ga-emerịrị: "Aga m ahapụ mkparịta ụka ahụ ma ọ bụrụ na ọ ghọọ enweghị nkwanye ugwu" karịa "ị ga-akwụsị enweghị nkwanye ugwu."\n\nMaka ndị nwere akụkọ ihe mere eme nke mmerụ ahụ-mmụọ, ịtọ oke nwere ike ịdị ka enweghị nchekwa na mbụ, karịsịa ma ọ bụrụ na mmekọrịta gara aga tarala ikwu eziokwu ahụhụ. Ọ bụ ihe a na-ahụkarị iji rịọ mgbaghara karịa oke ma ọ bụ ime ka oke dị nro ruo mgbe ọ tụfuru ihe ọ pụtara. Ịme omume oke n''ọnọdụ dị ala tupu na-enyere aka iwulite nkà ahụ tupu ịchọ ya ebe ọ dị mkpa karịa.\n\nOke e kwuru mana a na-edoghị ya abụghị ezi oke -- ịnọgide, ọbụlagodi n''ụzọ dị nta, bụ ihe na-eme ka ọ bụrụ ihe a pụrụ ịtụkwasị obi nye gị na onye ọzọ.'),
    ('00000000-0000-0000-0000-000000003102', 'fr', 'Poser et Maintenir des Limites', 'Une limite est une déclaration claire de ce dont vous avez besoin pour vous sentir en sécurité et respecté dans une relation -- ce n''est ni une punition, ni une tentative de contrôler le comportement de quelqu''un d''autre. Une limite décrit ce que VOUS allez faire, pas une exigence envers ce que l''autre personne doit faire : « je quitterai la conversation si elle devient irrespectueuse » plutôt que « tu dois arrêter d''être irrespectueux ».\n\nPour les personnes ayant un passé traumatique, poser des limites peut sembler risqué au début, surtout si des relations passées ont puni la franchise. Il est courant de trop s''excuser ou d''adoucir une limite jusqu''à ce qu''elle perde son sens. Pratiquer les limites dans des situations à faibles enjeux d''abord peut aider à développer cette compétence avant d''en avoir besoin là où cela compte davantage.\n\nUne limite communiquée puis non maintenue n''est pas vraiment une limite -- la constance, même de façon modeste, est ce qui la rend fiable, tant pour vous que pour l''autre personne.'),
    ('00000000-0000-0000-0000-000000003102', 'sw', 'Kuweka na Kudumisha Mipaka', 'Mpaka ni kauli iliyo wazi ya kile unachohitaji ili uhisi salama na kuheshimiwa katika uhusiano -- si adhabu, wala si kuhusu kudhibiti tabia ya mtu mwingine. Mpaka unaelezea kile WEWE utakachofanya, si madai ya kile mtu mwingine lazima afanye: "Nitaondoka kwenye mazungumzo ikiwa yatakosa heshima" badala ya "lazima uache kukosa heshima."\n\nKwa watu wenye historia ya kiwewe, kuweka mipaka kunaweza kuhisi bila usalama mwanzoni, hasa kama mahusiano ya awali yaliadhibu uwazi. Ni jambo la kawaida kuomba radhi kupita kiasi au kulainisha mpaka hadi upoteze maana yake. Kufanya mazoezi ya mipaka katika hali zenye hatari ndogo kwanza kunaweza kusaidia kujenga ujuzi huo kabla hujauhitaji mahali penye umuhimu zaidi.\n\nMpaka ulioelezwa lakini usiodumishwa si mpaka halisi -- uthabiti, hata kwa njia ndogo, ndio unaoufanya kuaminika kwako na kwa mtu mwingine.'),
    ('00000000-0000-0000-0000-000000003102', 'ar', 'وضع الحدود والحفاظ عليها', 'الحد هو بيان واضح لما تحتاجه لتشعر بالأمان والاحترام في العلاقة -- ليس عقابًا، وليس عن التحكم في سلوك شخص آخر. يصف الحد ما ستفعله أنت، وليس مطلبًا لما يجب أن يفعله الشخص الآخر: "سأغادر المحادثة إذا أصبحت غير محترمة" بدلًا من "يجب أن تتوقف عن قلة الاحترام".\n\nبالنسبة للأشخاص الذين لديهم تاريخ من الصدمة، قد يبدو وضع الحدود غير آمن في البداية، خاصة إذا عاقبت العلاقات السابقة الصراحة. من الشائع الإفراط في الاعتذار أو تخفيف الحد حتى يفقد معناه. يمكن أن تساعد ممارسة الحدود في مواقف أقل خطورة أولاً على بناء هذه المهارة قبل الحاجة إليها في مكان أكثر أهمية.\n\nالحد الذي يُعبَّر عنه ولا يُحافَظ عليه ليس حدًا حقيقيًا -- الاتساق، حتى بطرق صغيرة، هو ما يجعله جديرًا بالثقة لك وللشخص الآخر.'),

    ('00000000-0000-0000-0000-000000003103', 'pcm', 'How To Build Trust Again After Trauma', 'Trauma, especially the one wey another person cause, fit make trust feel risky for any relationship afterward -- even the ones wey never give any reason to worry. Dis one no be character flaw; na protection mechanism wey generalize from one specific threat go threats in general.\n\nTo build trust again dey normally happen small-small, through small and consistent experience instead of just one conversation wey reassure you. To notice when person action match their word over time -- no be just to believe one promise -- na often better and more reliable gauge pass how safe situation feel at first.\n\nE dey also reasonable make you extend trust for different pace for different relationship. To trust slowly no be the same as say you no fit trust at all -- e fit be sign say you dey careful about something wey matter.'),
    ('00000000-0000-0000-0000-000000003103', 'yo', 'Kíkọ́ Ìgbẹ́kẹ̀lé Padà Lẹ́yìn Ìpalára-Ọkàn', 'Ìpalára-ọkàn, pàápàá èyí tí ẹlòmíràn fà, lè mú kí ìgbẹ́kẹ̀lé dàbí ewu nínú àjọṣe èyíkéyìí lẹ́yìn náà -- kódà àwọn tí kò tí ì fúnni ní ìdí kankan láti ṣàníyàn. Èyí kì í ṣe àbàwọ́n ìwà; ó jẹ́ ẹ̀rọ ìdáàbòbò tí ó gbòòrò láti ewu kan pàtó sí ewu ní gbogbogbòò.\n\nKíkọ́ ìgbẹ́kẹ̀lé padà sábà máa ń ṣẹlẹ̀ díẹ̀díẹ̀, nípasẹ̀ àwọn ìrírí kéékèèké àti aṣepé dípò ọ̀rọ̀ ìfọ̀kànbalẹ̀ kan ṣoṣo. Ṣíṣàkíyèsí ìgbà tí ìṣe ẹnìkan bá bá ọ̀rọ̀ wọn mu ní àkókò -- kì í ṣe gbígba ìlérí kan ṣoṣo gbọ́ nìkan -- sábà máa ń jẹ́ ìdíwọ̀n tí ó ṣeé gbẹ́kẹ̀lé ju bí ipò kan ṣe dà bí àbò ní àkọ́kọ́ lọ.\n\nÓ tún bọ́gbọ́n mu láti fa ìgbẹ́kẹ̀lé jáde ní onírúurú ìyára nínú onírúurú àjọṣe. Láti gbẹ́kẹ̀lé díẹ̀díẹ̀ kì í ṣe bákan náà pẹ̀lú àìlè gbẹ́kẹ̀lé rárá -- ó lè jẹ́ àmì pé o ń ronú jinlẹ̀ nípa ohun kan tí ó ṣe pàtàkì.'),
    ('00000000-0000-0000-0000-000000003103', 'ha', 'Sake Gina Amana Bayan Rauni', 'Rauni, musamman wanda wani mutum ya haddasa, na iya sa amana ta ji kamar hadari a cikin kowace dangantaka bayan haka -- ko da wadanda ba su taba ba da dalilin damuwa ba. Wannan ba lahani na hali ba ne; dabara ce ta kariya wacce ta zama gama-gari daga wani hatsari na musamman zuwa hatsarori gaba daya.\n\nSake gina amana yakan faru a hankali-hankali, ta hanyar kananan abubuwa masu dagewa maimakon tattaunawa daya mai tabbatarwa. Lura da lokacin da ayyukan wani suka yi daidai da maganarsu cikin lokaci -- ba kawai yarda da alkawari daya ba -- galibi shi ne mafi amintaccen awo fiye da yadda yanayi ya ji na farko.\n\nHaka kuma yana da hankali a bai wa amana gudu daban-daban a dangantakoki daban-daban. Amincewa a hankali ba daidai yake da rashin iya amincewa ba -- yana iya zama alama cewa kana da tunani mai zurfi game da wani abu mai muhimmanci.'),
    ('00000000-0000-0000-0000-000000003103', 'ig', 'Iwughachi Ntụkwasị Obi Mgbe Mmerụ Ahụ-Mmụọ Gasịrị', 'Mmerụ ahụ-mmụọ, karịsịa nke onye ọzọ kpatara, nwere ike ime ka ntụkwasị obi dị ka ihe ize ndụ na mmekọrịta ọ bụla mgbe ahụ gasịrị -- ọbụlagodi ndị na-enwebeghị ihe mgbagwoju anya ọ bụla. Nke a abụghị ntụpọ agwa; ọ bụ usoro nchebe nke gbasaworo site n''otu ihe ize ndụ akọwapụtara gaa n''ihe ize ndụ n''ozuzu.\n\nIwughachi ntụkwasị obi na-adịkarị eme nwayọọ nwayọọ, site n''obere ahụmịhe na-adịgide adịgide karịa otu mkparịta ụka na-enye nchekwa obi. ịhụ mgbe omume onye mere ka o kwekọọ na okwu ha oge niile -- ọ bụghị naanị ikwere otu nkwa -- bụkarị ihe ọtụtụ a na-enwe ntụkwasị obi karịa otú ọnọdụ dị na mbụ.\n\nọ bụkwa ihe ziri ezi ịgbasa ntụkwasị obi n''ọsọ dị iche iche na mmekọrịta dị iche iche. Ịtụkwasị obi nwayọọ nwayọọ abụghị otu ihe ya na enweghị ike ịtụkwasị obi -- ọ nwere ike ịbụ ihe ngosi na ị na-eche echiche miri emi gbasara ihe dị mkpa.'),
    ('00000000-0000-0000-0000-000000003103', 'fr', 'Reconstruire la Confiance Après un Traumatisme', 'Le traumatisme, en particulier celui causé par une autre personne, peut rendre la confiance risquée dans n''importe quelle relation par la suite -- même celles qui n''ont donné aucune raison de s''inquiéter. Ce n''est pas un défaut de caractère ; c''est un mécanisme de protection qui s''est généralisé d''une menace spécifique aux menaces en général.\n\nReconstruire la confiance se fait généralement progressivement, à travers de petites expériences constantes plutôt qu''une seule conversation rassurante. Remarquer que les actions de quelqu''un correspondent à ses paroles au fil du temps -- pas seulement croire une seule promesse -- est souvent un indicateur plus fiable que le sentiment initial de sécurité d''une situation.\n\nIl est également raisonnable d''accorder sa confiance à des rythmes différents selon les relations. Faire confiance lentement n''est pas la même chose qu''être incapable de faire confiance -- cela peut être le signe que vous êtes réfléchi au sujet de quelque chose d''important.'),
    ('00000000-0000-0000-0000-000000003103', 'sw', 'Kujenga Upya Imani Baada ya Kiwewe', 'Kiwewe, hasa kile kilichosababishwa na mtu mwingine, kinaweza kufanya imani ihisi hatari katika uhusiano wowote baadaye -- hata ile isiyotoa sababu yoyote ya wasiwasi. Hili si dosari ya tabia; ni mkakati wa kujikinga uliojumlishwa kutoka hatari maalum kwenda hatari kwa ujumla.\n\nKujenga upya imani kwa kawaida hutokea pole pole, kupitia uzoefu mdogo na thabiti badala ya mazungumzo moja ya kutuliza. Kutambua wakati matendo ya mtu yanalingana na maneno yake kwa muda -- si tu kuamini ahadi moja -- mara nyingi ni kipimo cha kuaminika zaidi kuliko jinsi hali inavyohisi mwanzoni.\n\nNi busara pia kutoa imani kwa kasi tofauti katika mahusiano tofauti. Kuamini pole pole si sawa na kutokuwa na uwezo wa kuamini -- inaweza kuwa ishara kwamba unafikiria kwa makini kuhusu jambo lenye umuhimu.'),
    ('00000000-0000-0000-0000-000000003103', 'ar', 'إعادة بناء الثقة بعد الصدمة', 'يمكن للصدمة، خاصة تلك التي يسببها شخص آخر، أن تجعل الثقة تبدو محفوفة بالمخاطر في أي علاقة لاحقة -- حتى تلك التي لم تعطِ أي سبب للقلق. هذا ليس عيبًا في الشخصية؛ إنه آلية حماية تعممت من تهديد معين إلى التهديدات بشكل عام.\n\nعادة ما تحدث إعادة بناء الثقة تدريجيًا، من خلال تجارب صغيرة ومتسقة بدلاً من محادثة طمأنة واحدة. ملاحظة تطابق أفعال شخص ما مع كلماته بمرور الوقت -- وليس مجرد تصديق وعد واحد -- غالبًا ما يكون مقياسًا أكثر موثوقية من مدى شعور الموقف بالأمان في البداية.\n\nمن المعقول أيضًا منح الثقة بوتيرات مختلفة في علاقات مختلفة. الثقة ببطء ليست نفس الشيء مثل عدم القدرة على الثقة -- يمكن أن تكون علامة على أنك متأنٍّ بشأن أمر مهم.');

INSERT INTO quiz_question_translations (question_id, locale, text) VALUES
    ('00000000-0000-0000-0000-000000003301', 'pcm', 'How you fit use attachment style well, according to dis lesson?'),
    ('00000000-0000-0000-0000-000000003301', 'yo', 'Báwo ni a ṣe lè lo ìlànà ìfarapọ̀ dáradára, gẹ́gẹ́ bí ẹ̀kọ́ yìí ṣe sọ?'),
    ('00000000-0000-0000-0000-000000003301', 'ha', 'Ta yaya ya kamata a yi amfani da salon kulla alaka sosai, bisa ga wannan darasi?'),
    ('00000000-0000-0000-0000-000000003301', 'ig', 'Olee otú kacha mma e si eji ụdị ijikọ, dịka nkuzi a kwuru?'),
    ('00000000-0000-0000-0000-000000003301', 'fr', 'Comment le style d''attachement est-il le mieux utilisé, selon cette leçon ?'),
    ('00000000-0000-0000-0000-000000003301', 'sw', 'Mtindo wa kujishikamanisha unatumikaje vizuri zaidi, kulingana na somo hili?'),
    ('00000000-0000-0000-0000-000000003301', 'ar', 'كيف يُستخدم نمط التعلق على أفضل وجه، وفقًا لهذا الدرس؟'),

    ('00000000-0000-0000-0000-000000003302', 'pcm', 'Which one of dis na example of boundary, as dis lesson talk am?'),
    ('00000000-0000-0000-0000-000000003302', 'yo', 'Èwo lára àwọn wọ̀nyí ni àpẹẹrẹ òpin, gẹ́gẹ́ bí ẹ̀kọ́ yìí ṣe ṣàpèjúwe?'),
    ('00000000-0000-0000-0000-000000003302', 'ha', 'Wane daga cikin wadannan misali ne na iyaka, kamar yadda wannan darasi ya bayyana?'),
    ('00000000-0000-0000-0000-000000003302', 'ig', 'Kedu nke n''ime ndị a bụ ihe atụ nke oke, dịka nkuzi a kọwara?'),
    ('00000000-0000-0000-0000-000000003302', 'fr', 'Lequel de ces énoncés est un exemple de limite, tel que décrit dans cette leçon ?'),
    ('00000000-0000-0000-0000-000000003302', 'sw', 'Ni ipi kati ya haya ni mfano wa mpaka, kama ilivyoelezwa katika somo hili?'),
    ('00000000-0000-0000-0000-000000003302', 'ar', 'أي من هذه مثال على حد، كما ورد في هذا الدرس؟'),

    ('00000000-0000-0000-0000-000000003303', 'pcm', 'Wetin dis lesson talk say dey often better and reliable sign of trust pass one single promise?'),
    ('00000000-0000-0000-0000-000000003303', 'yo', 'Kí ni ẹ̀kọ́ yìí sọ pé ó máa ń jẹ́ ìdíwọ̀n ìgbẹ́kẹ̀lé tí ó ṣeé gbẹ́kẹ̀lé ju ìlérí kan ṣoṣo lọ?'),
    ('00000000-0000-0000-0000-000000003303', 'ha', 'Mene ne wannan darasi ya ce galibi shi ne awo mafi amintacci na amana fiye da alkawari daya?'),
    ('00000000-0000-0000-0000-000000003303', 'ig', 'Gịnị ka nkuzi a kwuru na ọ na-abụkarị ihe ọtụtụ ntụkwasị obi ka a pụrụ ịdabere na ya karịa otu nkwa?'),
    ('00000000-0000-0000-0000-000000003303', 'fr', 'Que dit cette leçon être souvent un indicateur de confiance plus fiable qu''une seule promesse ?'),
    ('00000000-0000-0000-0000-000000003303', 'sw', 'Somo hili linasema ni nini mara nyingi kipimo cha kuaminika zaidi cha imani kuliko ahadi moja?'),
    ('00000000-0000-0000-0000-000000003303', 'ar', 'ماذا يقول هذا الدرس إنه غالبًا مقياس أكثر موثوقية للثقة من وعد واحد؟');

