    ('00000000-0000-0000-0000-000000003413', 'pcm', '"You always dey do me like dis"'),
    ('00000000-0000-0000-0000-000000003413', 'yo', '"O máa ń ṣe mí báyìí nígbà gbogbo"'),
    ('00000000-0000-0000-0000-000000003413', 'ha', '"Kullum kana min haka"'),
