    ('00000000-0000-0000-0000-000000003413', 'ar', '"أنت دائمًا تفعل بي هذا"'),

    ('00000000-0000-0000-0000-000000003414', 'pcm', '"I guess e fine, no worry about am"'),
    ('00000000-0000-0000-0000-000000003414', 'yo', '"Mo rò pé ó dára, má ṣàníyàn nípa rẹ̀"'),
    ('00000000-0000-0000-0000-000000003414', 'ha', '"Ina tsammanin lafiya, kada ka damu da shi"'),
